using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
public static class RuinsJointsReview{
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static Color32[] Shot(Camera c,Vector3 from,Vector3 at,string file){c.transform.position=from;c.transform.LookAt(at);var rt=new RenderTexture(1200,900,24);c.targetTexture=rt;for(int i=0;i<3;i++)c.Render();Check(!ShaderUtil.ShaderHasError(Shader.Find("MapRuins/AgedLimestone")),"Shader failure");var previous=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(1200,900,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1200,900),0,0);t.Apply();File.WriteAllBytes(file,t.EncodeToPNG());var pixels=t.GetPixels32();RenderTexture.active=previous;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(t);UnityEngine.Object.DestroyImmediate(rt);return pixels;}
 public static void Run(){const string ev="Evidence/Target30Joints";Directory.CreateDirectory(ev);try{
 EditorSceneManager.OpenScene("Assets/RuinsTarget30Output/Room.unity");var current=GameObject.Find("ruins_1").transform.parent.gameObject;var baseline=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget28Output/Structures/Ruins.prefab"));Check(baseline!=null,"Baseline missing");var c=UnityEngine.Object.FindAnyObjectByType<Camera>();c.orthographic=false;c.backgroundColor=new Color(.075f,.085f,.1f);RenderSettings.ambientLight=Color.gray*.65f;var sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).First(l=>l.type==LightType.Directional);sun.transform.rotation=Quaternion.Euler(38,-28,0);
 foreach(var state in new[]{false,true}){baseline.SetActive(!state);current.SetActive(state);Shot(c,new Vector3(15,20,19),new Vector3(0,3.5f,0),ev+"/room-"+(state?"after":"before")+".png");Shot(c,new Vector3(7,8,10),new Vector3(0,4,3),ev+"/assembly-"+(state?"after":"before")+".png");}
 var ids=new[]{"ruins_1","ruins_4","ruins_9","ruins_11","ruins_18"};var names=new[]{"inner","outer","tee","end","stairs"};
 for(int i=0;i<ids.Length;i++){
  foreach(var root in new[]{baseline,current})foreach(Transform child in root.transform)child.gameObject.SetActive(child.name==ids[i]);
  var target=current.transform.Find(ids[i]).GetComponent<MeshRenderer>();var centre=target.bounds.center;c.orthographic=true;c.orthographicSize=i==4?3:1.8f;
  var offset=i==4?new Vector3(4,5,7):new Vector3(4,3,5);
  foreach(var state in new[]{false,true}){baseline.SetActive(!state);current.SetActive(state);Shot(c,centre+offset,centre,ev+"/"+names[i]+"-"+(state?"after":"before")+".png");}
  sun.transform.rotation=Quaternion.Euler(25,140,0);Shot(c,centre+offset,centre,ev+"/"+names[i]+"-opposite.png");sun.transform.rotation=Quaternion.Euler(38,-28,0);
 }
 foreach(var root in new[]{baseline,current})foreach(Transform child in root.transform)child.gameObject.SetActive(true);baseline.SetActive(false);current.SetActive(true);
 var changed=new[]{1,2,3,4,9,11,12,14,18}.Select(i=>"ruins_"+i).ToArray();foreach(var root in new[]{baseline,current})foreach(var id in changed)root.transform.Find(id).gameObject.SetActive(false);c.orthographic=false;
 baseline.SetActive(true);current.SetActive(false);var before=Shot(c,new Vector3(15,20,19),new Vector3(0,3.5f,0),ev+"/unchanged-before.png");baseline.SetActive(false);current.SetActive(true);var after=Shot(c,new Vector3(15,20,19),new Vector3(0,3.5f,0),ev+"/unchanged-after.png");Check(before.SequenceEqual(after),"Existing part image changed");foreach(var id in changed)current.transform.Find(id).gameObject.SetActive(true);
 foreach(var id in ids){var template=current.transform.Find(id).gameObject;var r=template.GetComponent<MeshRenderer>();Check(r.sharedMaterial.IsKeywordEnabled("_RUINS_ORNAMENT"),"New part material keyword");Check(template.GetComponent<MeshCollider>().sharedMesh==template.GetComponent<MeshFilter>().sharedMesh,"Collider identity");foreach(int count in new[]{9,225}){var clones=Enumerable.Range(0,count).Select(i=>{var g=UnityEngine.Object.Instantiate(template);g.transform.position=new Vector3(100+i*5,3,100);return g;}).ToArray();Check(clones.Select(g=>g.GetComponent<MeshFilter>().sharedMesh).Distinct().Count()==1&&clones.Select(g=>g.GetComponent<MeshRenderer>().sharedMaterial).Distinct().Count()==1,"Shared resources");foreach(var g in clones)UnityEngine.Object.DestroyImmediate(g);}}
 File.WriteAllText(ev+"/result.json","{\"pass\":true,\"newKinds\":5,\"sameCameraBeforeAfter\":true,\"existingPartPixelDelta\":0,\"shared9And225\":true,\"colliderIdentity\":true,\"gpuMeasured\":false}");EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(ev+"/failure.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}
